// Merkt sich, was der Simulator braucht (alles über MQTT, retained):
//   .../static/stations    Stationsliste (Lage, Kapazität)
//   .../profiles/+/+       Routen -> Start- und Zielstation
//   .../live/bicimad/+     echte Werte als Ausgangspunkt der Simulation
//   .../live/weather       echtes Wetter als Ausgangspunkt
// Eigene simulierte Nachrichten (sim: ...) werden ignoriert.
const t = msg.topic || '';
const p = msg.payload;
const empty = p === '' || p == null || (Buffer.isBuffer(p) && p.length === 0);
if (t.endsWith('/static/stations')) {
    const map = {};
    (Array.isArray(p) ? p : []).forEach(s => { map[s.id] = s; });
    flow.set('stations', map);
} else if (t.indexOf('/profiles/') >= 0) {
    const key = t.split('/').slice(-2).join('/');
    const routes = flow.get('routes') || {};
    if (empty || typeof p !== 'object') delete routes[key];
    else routes[key] = { from: p.from.id, to: p.to.id };
    flow.set('routes', routes);
} else if (t.indexOf('/live/bicimad/') >= 0) {
    if (empty || typeof p !== 'object' || p.sim || p.demo) return null;
    const real = flow.get('realBikes') || {};
    real[t.split('/').pop()] = { bikes: p.bikes, docks: p.docks };
    flow.set('realBikes', real);
} else if (t.endsWith('/live/weather')) {
    if (empty || typeof p !== 'object' || p.sim || p.demo) return null;
    flow.set('realWeather', { temp: p.temp, precip: p.precip, wind: p.wind });
}
const n = Object.keys(flow.get('stations') || {}).length;
node.status({ fill: n ? 'green' : 'yellow', shape: 'dot',
    text: n + ' Stationen, ' + Object.keys(flow.get('routes') || {}).length + ' Routen bekannt' });
return null;

// ============================================================
//  Simulator: erzeugt realistische Live-Daten für Vorführung und Tests.
//  Er ist ein eigener Dienst mit eigener Broker-Verbindung (g6-sim) und
//  veröffentlicht auf GENAU DENSELBEN Topics wie die Collectors
//  (.../live/bicimad/<id>, .../live/weather). Profil-Dienst, Empfehlung und
//  Dashboard merken davon nichts: Entkopplung über MQTT.
//
//  Steuerung: .../sim/cmd {scenario: 'demo'|'regen'|'station-leer'|'hitze'|'sturm'|'normal'|'stop'}
//  Zustand:   .../sim/state (retained) -> Collectors pausieren solange ihre Live-Werte.
//  Simuliert werden nur die Stationen, auf die es ankommt: Start- und Zielstationen
//  aller Routen und ihre 4 nächsten Nachbarn. Ausgangswerte = letzte echte Werte.
//  Ohne Stationsliste (kein Internet) legt er Ersatzstationen neben den festen Orten an.
// ============================================================
const cfg = global.get('cfg');
const P = cfg.prefix;
const STEP_S = 5;                 // Takt des Simulators (Inject "alle 5 s")
let sim = context.get('sim') || { active: false };
const out = [];

// ---------- Szenarien: Zeitleiste in Sekunden ab Start ----------
// weather: Wetter zum Zeitpunkt t | start: Zielwert für Räder an den STARTstationen (oder null)
const SCEN = {
    normal: { label: 'Normaler Werktag', phases: [[0, 'trocken, 16 °C, genug Räder']],
        weather: t => ({ temp: 16, precip: 0, wind: 8 }), start: t => null },
    regen: { label: 'Regenschauer', phases: [[0, 'noch trocken'], [20, 'leichter Regen (0,3 mm)'],
            [60, 'starker Regen (1,8 mm)'], [150, 'Regen lässt nach (0,2 mm)'], [200, 'wieder trocken']],
        weather: t => ({ temp: 13, wind: 14, precip: t < 20 ? 0 : t < 60 ? 0.3 : t < 150 ? 1.8 : t < 200 ? 0.2 : 0 }),
        start: t => null },
    'station-leer': { label: 'Startstation leert sich', phases: [[0, 'genug Räder'], [15, 'Räder werden knapp'],
            [75, 'Startstationen leer'], [150, 'Umverteilung: Lieferwagen bringt Räder']],
        weather: t => ({ temp: 16, precip: 0, wind: 8 }),
        start: t => t < 15 ? null : t < 75 ? 2 : t < 150 ? 0 : 10 },
    hitze: { label: 'Hitzetag', phases: [[0, '38 °C, trocken']],
        weather: t => ({ temp: 38, precip: 0, wind: 6 }), start: t => null },
    sturm: { label: 'Sturm mit Nieselregen', phases: [[0, 'Wind 48 km/h, 0,4 mm Regen']],
        weather: t => ({ temp: 11, precip: 0.4, wind: 48 }), start: t => null },
    demo: { label: 'Demo-Ablauf (3 min)', phases: [[0, '1/5 trocken, genug Räder'], [20, '2/5 Startstationen werden knapp'],
            [50, '3/5 leichter Regen setzt ein'], [80, '4/5 starker Regen'],
            [130, '5/5 Regen vorbei, Umverteilung bringt Räder'], [170, 'Ende: normaler Betrieb']],
        weather: t => ({ temp: 15, wind: 10, precip: t < 50 ? 0 : t < 80 ? 0.3 : t < 130 ? 1.6 : 0 }),
        start: t => t < 20 ? null : t < 130 ? 2 : 10 }
};

// ---------- Zufall mit festem Startwert: jeder Lauf sieht gleich aus ----------
function rnd() {
    let a = (sim.seed = (sim.seed + 0x6D2B79F5) | 0);
    a = Math.imul(a ^ (a >>> 15), a | 1);
    a ^= a + Math.imul(a ^ (a >>> 7), a | 61);
    return ((a ^ (a >>> 14)) >>> 0) / 4294967296;
}
const dist = (a, b) => {
    const kx = 111320 * Math.cos(a.lat * Math.PI / 180), ky = 110540;
    return Math.hypot((a.lon - b.lon) * kx, (a.lat - b.lat) * ky);
};
const phaseAt = (sc, t) => sc.phases.filter(ph => ph[0] <= t).pop()[1];
const state = () => ({ topic: P + '/sim/state', qos: 1, retain: true,
    payload: { active: sim.active, scenario: sim.scenario, label: sim.label, phase: sim.phase,
        startedAt: sim.startedAt, stations: Object.keys(sim.st || {}).length } });

// Ersatzstationen neben den festen Orten (nur ohne echte Stationsliste, z. B. offline)
function fallbackStations() {
    return (cfg.places || []).map((p, i) => ({
        id: 'sim-' + p.id, name: 'SIM ' + p.label,
        lat: Math.round((p.lat + 0.0009) * 1e5) / 1e5, lon: Math.round((p.lon + (i % 2 ? 0.0008 : -0.0008)) * 1e5) / 1e5,
        capacity: 18 + (i % 4) * 3
    }));
}

// Welche Stationen werden simuliert? Start/Ziel jeder Route + je 4 nächste Nachbarn
function relevant() {
    const stations = flow.get('stations') || {};
    const list = Object.values(stations);
    const routes = flow.get('routes') || {};
    const ids = {}, starts = {};
    for (const r of Object.values(routes)) {
        for (const id of [r.from, r.to]) {
            const s = stations[id];
            if (!s) continue;
            ids[id] = true;
            list.map(o => ({ id: o.id, d: dist(s, o) })).sort((a, b) => a.d - b.d).slice(1, 5)
                .forEach(o => { ids[o.id] = true; });
        }
        starts[r.from] = true;
    }
    return { ids: Object.keys(ids), starts: starts, stations: stations };
}

// ---------- Kommando ----------
if (msg.topic && msg.topic.endsWith('/sim/cmd')) {
    const sc = msg.payload && msg.payload.scenario;
    if (sc === 'stop') {
        if (!sim.active) return null;
        sim = { active: false };
        context.set('sim', sim);
        node.status({ fill: 'grey', shape: 'ring', text: 'gestoppt' });
        // Collectors sollen sofort wieder alle echten Werte senden
        return [[state(),
            { topic: P + '/cmd/bicimad/refresh', payload: 'refresh', qos: 1, retain: false },
            { topic: P + '/cmd/weather/refresh', payload: 'refresh', qos: 1, retain: false }]];
    }
    if (!SCEN[sc]) { node.warn('Unbekanntes Szenario: ' + sc); return null; }
    if (!Object.keys(flow.get('stations') || {}).length) {
        // Offline: Ersatzstationen veröffentlichen, damit der Profil-Dienst rechnen kann
        const fb = fallbackStations();
        const map = {}; fb.forEach(s => { map[s.id] = s; });
        flow.set('stations', map);
        out.push({ topic: P + '/static/stations', payload: fb, qos: 1, retain: true });
        node.warn('Keine Stationsliste vom Collector: ' + fb.length + ' Ersatzstationen (SIM) veröffentlicht');
    }
    const keep = sim.active ? sim.st : null;   // laufende Simulation: Werte weiterverwenden
    sim = { active: true, scenario: sc, label: SCEN[sc].label, startedAt: Date.now(), seed: 20261118,
        st: keep || {}, w: null, phase: null, lastFull: 0 };
}

// Nach einem Neustart von Node-RED einmal den eigenen Zustand melden. Sonst würde ein
// alter retained Zustand "aktiv" die Collectors dauerhaft pausieren.
if (!context.get('announced')) {
    context.set('announced', true);
    if (!sim.active) out.push(state());
}
// Heartbeat (wie bei den Collectors): jede Minute "online" bestätigen. Korrigiert einen
// veralteten Status, falls der Broker eine alte Close-/Last-Will-Nachricht nachliefert.
if (Date.now() - (context.get('beat') || 0) > 60000) {
    context.set('beat', Date.now());
    out.push({ topic: P + '/system/sim', payload: 'online', qos: 1, retain: true });
}
if (!sim.active) { context.set('sim', sim); return out.length ? [out] : null; }

// ---------- Schritt ----------
const sc = SCEN[sim.scenario];
const t = (Date.now() - sim.startedAt) / 1000;
const rel = relevant();
const real = flow.get('realBikes') || {};
const full = Date.now() - sim.lastFull > 60000;   // spätestens jede Minute alles neu (frische Zeitstempel)
if (full) sim.lastFull = Date.now();

// Stationen
const targetStart = sc.start(t);
let changed = 0;
for (const id of rel.ids) {
    const info = rel.stations[id];
    const cap = info.capacity || 20;
    let s = sim.st[id];
    if (!s) {
        // Ausgangswert: letzter echter Wert, sonst 35-65 % der Kapazität
        const r = real[id];
        const b = r ? r.bikes : Math.round(cap * (0.35 + 0.3 * rnd()));
        s = sim.st[id] = { bikes: b, cap: cap, sent: null };
    }
    const before = s.bikes;
    if (rel.starts[id] && targetStart !== null) {
        // Zielwert des Szenarios ansteuern, höchstens 3 Räder pro Schritt (wie in echt)
        const d = targetStart - s.bikes;
        s.bikes += Math.max(-3, Math.min(3, d));
    } else if (rnd() < 0.3) {
        // Normaler Betrieb: Leute leihen aus und geben zurück (±1)
        s.bikes += rnd() < 0.5 ? -1 : 1;
        // Startstationen im Normalbetrieb nicht zufällig leer laufen lassen
        if (rel.starts[id] && s.bikes < 4) s.bikes = 4;
    }
    s.bikes = Math.max(0, Math.min(cap, s.bikes));
    if (s.bikes !== before || s.sent === null || full) {
        s.sent = Date.now();
        changed++;
        out.push({ topic: P + '/live/bicimad/' + id, qos: 0, retain: true,
            payload: { bikes: s.bikes, docks: cap - s.bikes, renting: true, returning: true,
                ts: Date.now(), demo: true, sim: sim.scenario } });
    }
}

// Wetter
const w = sc.weather(t);
const wKey = [w.temp, w.precip, w.wind].join('/');
if (wKey !== sim.w || full) {
    sim.w = wKey;
    const code = w.precip >= 1 ? 65 : w.precip > 0 ? 61 : 1;   // WMO: starker / leichter Regen / heiter
    out.push({ topic: P + '/live/weather', qos: 0, retain: true,
        payload: { temp: w.temp, precip: w.precip, wind: w.wind, code: code, ts: Date.now(),
            demo: true, source: 'simulation', sim: sim.scenario } });
}

// Phase -> Zustand (retained), damit Dashboard und Collectors Bescheid wissen
const ph = phaseAt(sc, t);
if (ph !== sim.phase || msg.topic && msg.topic.endsWith('/sim/cmd')) {
    sim.phase = ph;
    out.push(state());
}
context.set('sim', sim);
node.status({ fill: 'blue', shape: 'dot', text: sim.label + ': ' + ph + ' (' + Math.round(t) + ' s, ' +
    rel.ids.length + ' Stationen)' });
return out.length ? [out] : null;
